mapper.select:
SELECT d.id, d.categoryId, d.dishName, d.description, d.coverImage, d.price, d.saleNumber, d.isRecommended, d.isNew, COALESCE(clicks.clickCount, 0) AS clickCount, CASE WHEN COALESCE(clicks.clickCount, 0) > 0 THEN '根据你的点击记录推荐' ELSE '本店热门菜品' END AS recommendationReason FROM dish d LEFT JOIN ( SELECT dishId, SUM(browseCount) AS clickCount FROM browseHistory
userId = #{userId}
GROUP BY dishId ) clicks ON clicks.dishId = d.id WHERE d.status = 1 ORDER BY COALESCE(clicks.clickCount, 0) DESC, d.isRecommended DESC, d.saleNumber DESC LIMIT #{limit}
